"""Isolated regression checks: only synthetic files and mocked subprocess calls.

Helper source is compiled with only absolute task-root literals redirected into
fresh temporary fixtures; every subprocess entry point is patched fail-closed.
No actual Git/GitHub/network command is executed.
"""
import ast,contextlib,datetime,hashlib,io,json,os,shutil,subprocess,sys,tempfile,unittest
from pathlib import Path
from unittest.mock import patch
sys.path.insert(0,'/private/tmp')
import cmm_round97_guards as guards
T=Path('/private/tmp'); RESULTS=[]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def fixture(root):
 for name in guards.PUBLICATION_FILES:
  if name.endswith('.py'):shutil.copy2(T/name,root/name)
 cfg={'base':'b'*40,'branch':'owned-test','title':'Bound title','counts':{'record_count':1}}
 (root/'cmm-round97-helper-config.json').write_text(json.dumps(cfg))
 (root/'cmm-round97-pr-body.md').write_text('Bound body.\n')
 bindings=guards.publication_bindings(root)
 prepared={'passed':True,'base':cfg['base'],'head':cfg['base'],'files':{'data/records/test.yaml':'a'*64},'bindings':bindings,'publication_bindings':bindings}
 pp=root/'cmm-round97-publication-prepared.json';pp.write_text(json.dumps(prepared))
 commit={'base':cfg['base'],'branch':cfg['branch'],'head':'c'*40,'tree':'d'*40,'worktree':str(root/'CMMMech-expansion-round97-20261015'),'files':list(prepared['files']),'hashes':prepared['files'],'bindings':bindings,'publication_bindings':bindings,'preparation_sha256':sha(pp)}
 (root/'cmm-round97-commit-receipt.json').write_text(json.dumps(commit))
 return commit,cfg,bindings
class Roots(ast.NodeTransformer):
 def __init__(self,root):self.root=str(root)
 def visit_Constant(self,node):
  if isinstance(node.value,str) and node.value.startswith('/private/tmp'):
   return ast.copy_location(ast.Constant(self.root+node.value[len('/private/tmp'):]),node)
  return node
def execute(name,root,argv=None,init=None):
 path=T/f'cmm-round97-{name}.py';tree=ast.fix_missing_locations(Roots(root).visit(ast.parse(path.read_text())))
 ns={'__name__':'__main__','__file__':str(root/path.name)}
 if init:ns.update(init)
 with patch.object(sys,'argv',[str(path),*(argv or [])]),contextlib.redirect_stdout(io.StringIO()):
  exec(compile(tree,str(path), 'exec'),ns)
 return ns
class RuntimeTests(unittest.TestCase):
 def test_occupied_outputs_fail_before_any_subprocess(self):
  outputs={'commit':'commit-receipt','publish':'pr-created','enqueue':'queue-receipt','cleanup':'pr-cleanup','sync-main':'main-sync'}
  for name,out in outputs.items():
   for kind in ['regular','dangling','directory']:
    with self.subTest(helper=name,kind=kind),tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
     root=Path(d);p=root/f'cmm-round97-{out}.json';target=root/'uncreated'
     if kind=='regular':p.write_text('PRESERVE')
     elif kind=='dangling':p.symlink_to(target)
     else:p.mkdir()
     with patch('subprocess.run',side_effect=AssertionError('forbidden subprocess')) as run,patch('subprocess.check_output',side_effect=AssertionError('forbidden subprocess')) as read:
      with self.assertRaises(FileExistsError):execute(name,root,['123'] if name in ['enqueue','cleanup'] else [])
      self.assertEqual(run.call_count+read.call_count,0)
     self.assertFalse(target.exists())
     if kind=='regular':self.assertEqual(p.read_text(),'PRESERVE')
 def test_stale_inputs_fail_before_publish_or_enqueue_subprocess(self):
  for helper in ['publish','enqueue']:
   for name in ['cmm-round97-helper-config.json','cmm-round97-pr-body.md','cmm-round97-cleanup.py','cmm-round97-publication-prepared.json']:
    with self.subTest(helper=helper,input=name),tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
     root=Path(d);fixture(root);p=root/name
     if name.endswith('.json'):
      data=json.loads(p.read_text());data['title']='CHANGED';p.write_text(json.dumps(data))
     else:p.write_text(p.read_text()+'changed\n')
     with patch('subprocess.run',side_effect=AssertionError('forbidden subprocess')) as run,patch('subprocess.check_output',side_effect=AssertionError('forbidden subprocess')) as read:
      with self.assertRaises(ValueError):execute(helper,root,['123'] if helper=='enqueue' else [])
      self.assertEqual(run.call_count+read.call_count,0)
 def test_verified_handoff_normal_and_missing_binding(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);c,cfg,b=fixture(root)
   self.assertEqual(guards.verified_handoff(root),(c,cfg,'Bound body.\n',b))
   c['bindings'].pop('cmm-round97-pr-body.md');(root/'cmm-round97-commit-receipt.json').write_text(json.dumps(c))
   with self.assertRaises(ValueError):guards.verified_handoff(root)
 def fake_publish(self,root,hook=None):
  c,cfg,b=fixture(root);actions=[];state={'pushed':False}
  def read(cmd,**kwargs):
   if cmd[:3]==['git','branch','--show-current']:return c['branch']+'\n'
   if cmd[:2]==['git','rev-parse']:return (c['tree'] if cmd[2]=='HEAD^{tree}' else c['head'])+'\n'
   if cmd[:2]==['git','rev-list']:return c['head']+' '+c['base']+'\n'
   if cmd[:2]==['git','status']:return ''
   if cmd[:2]==['git','ls-remote']:
    if cmd[-1]=='refs/heads/main':return c['base']+'\trefs/heads/main\n'
    if hook=='occupy' and not state['pushed']:(root/'cmm-round97-pr-created.json').write_text('CONCURRENT')
    return (c['head']+'\trefs/heads/'+c['branch']+'\n') if state['pushed'] else ''
   if cmd[:3]==['gh','pr','view']:return json.dumps({'number':123,'url':'https://example.test/123','headRefOid':c['head'],'baseRefOid':c['base'],'state':'OPEN','title':cfg['title'],'body':'Bound body.\n'})
   raise AssertionError('Unexpected read '+repr(cmd))
  def run(cmd,**kwargs):
   if cmd[:2]==['git','push']:
    actions.append('push');state['pushed']=True
    if hook=='body_after_push':(root/'cmm-round97-pr-body.md').write_text('changed after push')
    return subprocess.CompletedProcess(cmd,0,'','')
   if cmd[:3]==['gh','pr','create']:
    actions.append('create');self.assertEqual(kwargs['input'],'Bound body.\n');self.assertEqual(cmd[-2:],['--body-file','-'])
    return subprocess.CompletedProcess(cmd,0,'https://example.test/123\n','')
   raise AssertionError('Unexpected action '+repr(cmd))
  return c,cfg,b,actions,read,run
 def test_publish_normal_bound_stdin_and_exclusive_receipt(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);c,cfg,b,actions,read,run=self.fake_publish(root)
   with patch('subprocess.check_output',side_effect=read),patch('subprocess.run',side_effect=run):execute('publish',root)
   self.assertEqual(actions,['push','create']);result=json.loads((root/'cmm-round97-pr-created.json').read_text());self.assertEqual(result['publication_bindings'],b);self.assertEqual(result['pr']['title'],cfg['title'])
 def test_recheck_between_push_and_create(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);c,cfg,b,actions,read,run=self.fake_publish(root,'body_after_push')
   with patch('subprocess.check_output',side_effect=read),patch('subprocess.run',side_effect=run):
    with self.assertRaises(ValueError):execute('publish',root)
   self.assertEqual(actions,['push']);self.assertEqual(json.loads((root/'cmm-round97-pr-created.json').read_text())['state'],'failed')
 def test_late_collision_before_push(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);c,cfg,b,actions,read,run=self.fake_publish(root,'occupy')
   with patch('subprocess.check_output',side_effect=read),patch('subprocess.run',side_effect=run):
    with self.assertRaises(FileExistsError):execute('publish',root)
   self.assertEqual(actions,[]);self.assertEqual((root/'cmm-round97-pr-created.json').read_text(),'CONCURRENT')
 def test_exclusive_receipt_never_overwrites_and_retains_failure(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);out=root/'receipt';victim=root/'victim';victim.write_text('PRESERVE')
   with guards.ExclusiveReceipt(out) as receipt:receipt.finish({'passed':True})
   with self.assertRaises(FileExistsError):
    with guards.ExclusiveReceipt(out):pass
   failed=root/'failed'
   with self.assertRaises(RuntimeError):
    with guards.ExclusiveReceipt(failed):raise RuntimeError('mock failure')
   self.assertEqual(json.loads(failed.read_text())['state'],'failed')
   replaced=root/'replaced'
   with self.assertRaises(RuntimeError):
    with guards.ExclusiveReceipt(replaced) as receipt:
     replaced.unlink();replaced.symlink_to(victim);receipt.finish({'overwrite':True})
   self.assertEqual(victim.read_text(),'PRESERVE')
 def test_commit_check_only_has_no_git_mutation_or_receipt(self):
  with tempfile.TemporaryDirectory(prefix='cmm97-test-',dir='/private/tmp') as d:
   root=Path(d);path=T/'cmm-round97-commit.py';tree=ast.fix_missing_locations(Roots(root).visit(ast.parse(path.read_text())));ns={'__name__':'fixture_module','__file__':str(path)};exec(compile(tree,str(path),'exec'),ns)
   ns['collect']=lambda:({},[],{},{});ns['T']=root
   with patch.object(sys,'argv',[str(path),'--check-only']),patch('subprocess.run',side_effect=AssertionError('forbidden')),patch('subprocess.check_output',side_effect=AssertionError('forbidden')),contextlib.redirect_stdout(io.StringIO()):ns['main']()
   self.assertFalse((root/'cmm-round97-commit-receipt.json').exists())

if __name__=='__main__':
 suite=unittest.defaultTestLoader.loadTestsFromTestCase(RuntimeTests)
 result=unittest.TextTestRunner(verbosity=2).run(suite)
 receipt={'finished_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'passed':result.wasSuccessful(),'tests':result.testsRun,'failures':len(result.failures),'errors':len(result.errors),'scope':__doc__,'test_sha256':sha(__file__),'helper_hashes':{n:sha(T/n) for n in guards.PUBLICATION_FILES if n.endswith('.py')}}
 path=Path(os.environ.get('CMM97_TEST_RECEIPT','/private/tmp/cmm-round97-helper-fixes/regression-results-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')+'.json'))
 with path.open('x') as stream:json.dump(receipt,stream,indent=2);stream.write('\n')
 raise SystemExit(0 if result.wasSuccessful() else 1)
